/* ══════════════════════════════════════════════════════════════
   TOPIK II 쓰기 — 연습 문항
   ──────────────────────────────────────────────────────────────
   설계는 docs/topik-writing-plan.md 에 있다. 여기는 문항만 둔다.

   ── 출처와 저작권 ──────────────────────────────────────────
   **기출문제가 아니다.** 51·52번은 docs/spark-handoff.md 의 지침대로
   Gemini Spark 가 초안을 쓰고 사람이 검토한 창작 문항이고, 53·54번은
   같은 형식으로 여기서 직접 썼다. 유형과 난이도만 실제 시험을 따르고
   소재·인물·수치는 전부 지어낸 것이다.

   문항을 더할 때도 이 선을 지킨다. 기출 지문을 옮기거나 조금 고쳐
   쓰지 않는다.

   ── 이름 ───────────────────────────────────────────────────
   topik.js 는 main 이 **TOPIK I 읽기** 유형 연습에 쓰고 있다. 이건
   **TOPIK II 쓰기**라 다른 기능이므로 파일을 따로 둔다.

   ── 급 ─────────────────────────────────────────────────────
   51·52 는 중급, 53·54 는 고급으로 둔다. TOPIK II 안에서도 51·52 가
   3급 언저리, 53·54 가 4급 위라 단계로 갈리는 편이 낫다.
   값은 main 의 LEARN_LEVELS 를 그대로 쓴다 — 'intermediate' / 'advanced'.

   ── register (문체) ────────────────────────────────────────
   화면이 이 값으로 문체 경고를 낸다. AI 가 아니라 규칙이다.
     'formal' — 합니다체 (안내문·실용문).  해요체가 나오면 경고.
     'plain'  — -(느)ㄴ다체 (설명문·논술).  해요체와 합니다체 둘 다 경고.
   ══════════════════════════════════════════════════════════════ */

